export const getBulkImportPassagesUrl = () => {




  return `/api/passages/bulk-import`
}

/**
 * @summary Execute bulk passage import after validation
 */
export const bulkImportPassages = async (bulkImportInput: BulkImportInput, options?: RequestInit): Promise<BulkImportResult> => {

  return customFetch<BulkImportResult>(getBulkImportPassagesUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(bulkImportInput)
  }
);}




